# Golden values for fdars-core `register_fpca` (ALN-EXPFAM, GH #60).
#
# Reference: R registr 2.2.1 (CRAN), installed into ~/.cache/R-lib; fastglm not
# installed, so registr falls back to stats::glm for the template GLM.
#
# Data are generated by a portable LCG (identical in fdars' tests, see
# `alignment/expfam/tests.rs::sim`) following the design of
# `registr::simulate_unregistered_curves` (cubic Bernstein warps from
# `grid_subj_create`, mean -1.5 (sin 2 pi t + cos 2 pi t)).
#
# Run:  Rscript golden_registr.R > ../../../fdars-core/src/alignment/expfam/golden.rs
suppressMessages({
  .libPaths(c("~/.cache/R-lib", .libPaths()))
  library(registr)
})
stopifnot(as.character(packageVersion("registr")) == "2.2.1")
options(warn = -1)

# ---------------------------------------------------------------- LCG ----
lcg_state <- 12345
lcg_seed <- function(s) lcg_state <<- s
lcg_unif <- function() {
  lcg_state <<- (1664525 * lcg_state + 1013904223) %% 4294967296
  (lcg_state + 0.5) / 4294967296
}
lcg_norm <- function() {
  u1 <- lcg_unif(); u2 <- lcg_unif()
  sqrt(-2 * log(u1)) * cos(2 * pi * u2)
}
lcg_pois <- function(mu) {
  u <- lcg_unif(); k <- 0; p <- exp(-mu); f <- p
  while (u > f && k < 1000) { k <- k + 1; p <- p * mu / k; f <- f + p }
  k
}

# family: 0 gaussian, 1 binomial, 2 poisson, 3 gamma
# incompl: 0 complete, 1 leading (late start), 2 trailing (early end), 3 both
sim <- function(seed, n, m, family, incompl = 0) {
  lcg_seed(seed)
  grid <- seq(0, 1, length.out = m)
  out <- list()
  for (i in 1:n) {
    a <- 0.5 * lcg_norm()
    w <- c(lcg_unif(), lcg_unif(), lcg_unif())
    cw <- cumsum(w) / sum(w)
    s <- grid
    t_true <- 3 * s * (1 - s)^2 * cw[1] + 3 * s^2 * (1 - s) * cw[2] + s^3 * cw[3]
    lat <- -1.5 * (sin(2 * pi * t_true) + cos(2 * pi * t_true)) + a * sin(pi * t_true)
    val <- numeric(m)
    for (j in 1:m) {
      val[j] <- switch(family + 1,
        lat[j] + 0.1 * lcg_norm(),
        as.numeric(lcg_unif() < plogis(lat[j])),
        lcg_pois(exp(0.5 * lat[j] + 1)),
        exp(0.3 * lat[j]) / 4 * (-log(lcg_unif()) - log(lcg_unif()) - log(lcg_unif()) - log(lcg_unif()))
      )
    }
    lo <- 1; hi <- m
    if (incompl %in% c(1, 3)) lo <- 1 + floor(lcg_unif() * 0.3 * m)
    if (incompl %in% c(2, 3)) hi <- m - floor(lcg_unif() * 0.3 * m)
    out[[i]] <- data.frame(id = i, index = grid[lo:hi], value = val[lo:hi], t = t_true[lo:hi])
  }
  do.call(rbind, out)
}

# --------------------------------------------------------- emitters ----
fmt <- function(x) {
  s <- trimws(formatC(x, digits = 17, format = "g"))
  s <- ifelse(grepl("[.eE]", s) | grepl("inf|nan", s, ignore.case = TRUE), s, paste0(s, ".0"))
  s
}
emit <- function(name, x) {
  x <- as.numeric(x)
  cat(sprintf("pub(super) const %s: [f64; %d] = [\n", name, length(x)))
  cat(paste0("    ", fmt(x), ",\n"), sep = "")
  cat("];\n\n")
}
emit_scalar <- function(name, x) cat(sprintf("pub(super) const %s: f64 = %s;\n\n", name, fmt(x)))
emit_usize <- function(name, x) cat(sprintf("pub(super) const %s: usize = %d;\n\n", name, as.integer(x)))

glm_coefs <- function(Y, Kt, family, epsilon = 1e-8) {
  # registr's template GLM (registr_helper, obj = NULL, Y_template = NULL);
  # epsilon = 1e-8 is glm's default (what registr uses), 1e-14 the converged MLE.
  knots <- quantile(Y$index, probs = seq(0, 1, length = Kt - 2))[-c(1, Kt - 2)]
  B <- splines::bs(c(min(Y$index), max(Y$index), Y$index), knots = knots, intercept = TRUE)[-(1:2), ]
  fam <- if (family == "gamma") stats::Gamma(link = "log") else family
  coef(glm(Y$value ~ 0 + B, family = fam, control = glm.control(epsilon = epsilon, maxit = 200)))
}
emit_glm <- function(prefix, Y, Kt, family) {
  emit(paste0(prefix, "_GLM_COEFS"), glm_coefs(Y, Kt, family, 1e-14))
  emit(paste0(prefix, "_GLM_COEFS_REGISTR"), glm_coefs(Y, Kt, family))
}

cat("// @generated by .planning/quick/261126-8kh-aln-expfam-60-exponential-family-registr/golden_registr.R\n")
cat("// R registr 2.2.1 (stats::glm template fit; fastglm not installed). Data: portable LCG `sim`.\n")
cat("#![allow(clippy::unreadable_literal, clippy::excessive_precision)]\n\n")

# ------------------------------------------------- G: gaussian, npc 2 ----
Kt <- 8; Kh <- 4
Y <- sim(101, 15, 50, 0)
emit_scalar("G_DATA_SUM", sum(Y$value))
emit_glm("G", Y, Kt, "gaussian")
r0 <- registr(Y = Y, Kt = Kt, Kh = Kh, family = "gaussian", verbose = 0)
emit("G_INIT_BETA", r0$hinv_beta)   # Kh x n column-major
emit_scalar("G_INIT_LOSS", r0$loss)

# fpca_gauss on the initially registered data with a fixed psi init
Yr <- r0$Y
dc <- registr:::data_clean(Yr)
npc <- 2
set.seed(1988); psi0 <- matrix(rnorm(Kt * npc), Kt, npc) * 0.5
emit("G_PSI0", psi0)
fg <- fpca_gauss(Yr, npc = npc, Kt = Kt, maxiter = 50, error_thresh = 1e-4, seed = 1988, verbose = 0)
emit("G_FPCA_KNOTS", fg$knots)
emit("G_FPCA_MU", fg$mu)
emit("G_FPCA_EFUN", fg$efunctions)
emit("G_FPCA_EVAL", fg$evalues)
emit("G_FPCA_SUBJ", fg$subject_coefs)  # Kt x n
emit_scalar("G_FPCA_SIGMA2", fg$sigma2)

rf <- register_fpca(Y, family = "gaussian", npc = 2, Kt = Kt, Kh = Kh, verbose = 0)
emit("G_FULL_BETA", rf$hinv_beta)
emit("G_FULL_MU", rf$fpca_obj$mu)
emit("G_FULL_EFUN", rf$fpca_obj$efunctions)
emit("G_FULL_REGLOSS", rf$convergence$registration_loss)
emit_usize("G_FULL_ITER", rf$convergence$iterations)

# ------------------------------------------------- B: binomial, npc 1 ----
Y <- sim(202, 40, 60, 1)
emit_scalar("B_DATA_SUM", sum(Y$value))
emit_glm("B", Y, Kt, "binomial")
r0 <- registr(Y = Y, Kt = Kt, Kh = Kh, family = "binomial", verbose = 0)
emit("B_INIT_BETA", r0$hinv_beta)
emit_scalar("B_INIT_LOSS", r0$loss)

# bfpca internals with deterministic xi init (xi = 1) and psi from set.seed(1988)
Yr <- r0$Y
dc <- registr:::data_clean(Yr)
npc <- 1
prep <- registr:::bfpca_argPreparation(Y = dc$Y, Kt = Kt, time = dc$Y$index,
  t_min = min(dc$Y$index), t_max = max(dc$Y$index), periodic = FALSE,
  seed = 1988, subsample = TRUE, verbose = 0)
prep$xi[] <- 1
bo <- registr:::bfpca_optimization(npc = npc, npc_varExplained = NULL, Kt = Kt, maxiter = 50,
  print.iter = FALSE, seed = 1988, periodic = FALSE, error_thresh = 1e-4, verbose = 0,
  Y = dc$Y, rows = dc$Y_rows, I = dc$I, knots = prep$knots, Theta_phi = prep$Theta_phi,
  xi = prep$xi, alpha_coefs = prep$alpha_coefs)
set.seed(1988); psi0 <- matrix(rnorm(Kt * npc), Kt, npc) * 0.5
emit("B_PSI0", psi0)
emit("B_FPCA_ALPHA0", prep$alpha_coefs)
emit("B_FPCA_ALPHA", bo$alpha_coefs)
emit("B_FPCA_MU", bo$Theta_phi_mean %*% bo$alpha_coefs)
emit("B_FPCA_EFUN", bo$efunctions)
emit("B_FPCA_EVAL", bo$evalues)
emit("B_FPCA_SUBJ", bo$subject_coef)
emit_usize("B_FPCA_NITER", length(bo$error))

rf <- register_fpca(Y, family = "binomial", npc = 1, Kt = Kt, Kh = Kh, verbose = 0)
emit("B_FULL_BETA", rf$hinv_beta)
emit("B_FULL_MU", rf$fpca_obj$mu)
emit("B_FULL_EFUN", rf$fpca_obj$efunctions)
emit("B_FULL_REGLOSS", rf$convergence$registration_loss)
emit_usize("B_FULL_ITER", rf$convergence$iterations)

# ------------------------------------------------------- P: poisson ----
Y <- sim(303, 15, 50, 2)
emit_scalar("P_DATA_SUM", sum(Y$value))
emit_glm("P", Y, Kt, "poisson")
r0 <- registr(Y = Y, Kt = Kt, Kh = Kh, family = "poisson", verbose = 0)
emit("P_INIT_BETA", r0$hinv_beta)
emit_scalar("P_INIT_LOSS", r0$loss)
rf <- register_fpca(Y, family = "poisson", npc = 1, Kt = Kt, Kh = Kh, verbose = 0)
