emit("P_FULL_REGLOSS", rf$convergence$registration_loss)

# --------------------------------------------------------- Ga: gamma ----
Y <- sim(404, 15, 50, 3)
emit_scalar("GA_DATA_SUM", sum(Y$value))
emit_glm("GA", Y, Kt, "gamma")
r0 <- registr(Y = Y, Kt = Kt, Kh = Kh, family = "gamma", verbose = 0)
