# --------------------------------------------- incomplete gaussian ----
for (case in list(list("TR", 2, "trailing", 0.05), list("LE", 1, "leading", 0.05),
                  list("FU", 3, "full", 0.05))) {
  Y <- sim(505, 15, 50, 0, incompl = case[[2]])
  emit_scalar(paste0(case[[1]], "_DATA_SUM"), sum(Y$value))
  emit_usize(paste0(case[[1]], "_DATA_LEN"), nrow(Y))
  emit(paste0(case[[1]], "_GLM_COEFS_REGISTR"), glm_coefs(Y, Kt, "gaussian"))
  r0 <- registr(Y = Y, Kt = Kt, Kh = Kh, family = "gaussian", incompleteness = case[[3]],
                lambda_inc = case[[4]], verbose = 0)
  emit(paste0(case[[1]], "_INIT_BETA"), r0$hinv_beta)
  emit_scalar(paste0(case[[1]], "_INIT_LOSS"), r0$loss)
}
Y <- sim(505, 15, 50, 0, incompl = 2)
rf <- register_fpca(Y, family = "gaussian", npc = 1, Kt = Kt, Kh = Kh, incompleteness = "trailing",
                    lambda_inc = 0.05, verbose = 0)
emit("TR_FULL_BETA", rf$hinv_beta)
emit("TR_FULL_REGLOSS", rf$convergence$registration_loss)
